module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

    reg [3:0] cnt_10;
    reg [6:0] cnt_100;

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 0;
            CLK_10 <= 0;
            CLK_1 <= 0;
            cnt_10 <= 0;
            cnt_100 <= 0;
        end else begin
            CLK_50 <= ~CLK_50;

            cnt_10 <= cnt_10 + 1;
            if (cnt_10 == 9) begin
                CLK_10 <= ~CLK_10;
                cnt_10 <= 0;
            end

            cnt_100 <= cnt_100 + 1;
            if (cnt_100 == 99) begin
                CLK_1 <= ~CLK_1;
                cnt_100 <= 0;
            end
        end
    end

endmodule
